// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.bulk;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.Properties;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class CanonicalStatementStagerSidecarTest {

	@TempDir
	Path temporaryDirectory;

	@Test
	void publishesFixedWidthSizeIndexAndStoresItsDigestInWorkspaceState() throws Exception {
		Path target = temporaryDirectory.resolve("staged-store");
		CanonicalStagedInput staged;
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
			try (CanonicalStatementStager stager = stager(workspace.directory())) {
				stager.writeStatement(statement("a"));
				staged = stager.stagedInput();
			}
			workspace.recordStagedInput(staged);
			workspace.completePhase(BulkLoadPhase.STAGE_INPUTS);
		}

		Path control = BulkLoadWorkspace.controlDirectory(target);
		Path sizeIndex = CanonicalStagedInput.statementSizeIndexPath(control);
		assertThat(sizeIndex).isRegularFile();
		assertThat(Files.size(sizeIndex)).isEqualTo(48L + Long.BYTES);
		Properties state = BulkLoadWorkspace.inspect(control);
		assertThat(state.getProperty("stage.statement-digest")).isEqualTo(staged.statementDigest());
		assertThat(staged.statementDigest()).hasSize(64);
	}

	@Test
	void resumeRejectsSameCountAndSizeWithAStaleSidecarDigest() throws Exception {
		Path target = temporaryDirectory.resolve("stale-sidecar-store");
		Path control = BulkLoadWorkspace.controlDirectory(target);
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.STAGE_INPUTS);
			CanonicalStagedInput staged;
			try (CanonicalStatementStager stager = stager(workspace.directory())) {
				stager.writeStatement(statement("a"));
				staged = stager.stagedInput();
			}
			workspace.recordStagedInput(staged);
			workspace.completePhase(BulkLoadPhase.STAGE_INPUTS);
		}

		Path replacement = Files.createDirectory(temporaryDirectory.resolve("replacement"));
		try (CanonicalStatementStager stager = stager(replacement)) {
			stager.writeStatement(statement("b"));
			stager.stagedInput();
		}
		Files.copy(replacement.resolve("statements.lz4"), control.resolve("statements.lz4"),
				StandardCopyOption.REPLACE_EXISTING);

		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			CanonicalStagedInput staged = workspace.stagedInput(4);
			assertThatThrownBy(() -> {
				try (CanonicalStagedInput.RawStatementCursor cursor = staged.openRawStatementCursor()) {
					while (cursor.next() != null) {
						// Consume the logical stream so its digest can be verified.
					}
				}
			})
					.isInstanceOf(java.io.IOException.class)
					.hasMessageContaining("digest");
		}
	}

	@Test
	void reclaimsPublishedAndIncompleteSizeIndexesAfterResolution() throws Exception {
		Path target = temporaryDirectory.resolve("reclaim-sidecar-store");
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			Path published = CanonicalStagedInput.statementSizeIndexPath(workspace.directory());
			Path incomplete = CanonicalStagedInput.statementSizeIndexTemporaryPath(workspace.directory());
			Path componentRuns = Files.createDirectory(workspace.directory().resolve("resolved-component-runs"));
			Path valueComponentRuns = Files
					.createDirectory(workspace.directory().resolve("resolved-value-component-runs"));
			Files.writeString(published, "published");
			Files.writeString(incomplete, "incomplete");

			workspace.reclaimAfterResolution();

			assertThat(published).doesNotExist();
			assertThat(incomplete).doesNotExist();
			assertThat(componentRuns).doesNotExist();
			assertThat(valueComponentRuns).doesNotExist();
		}
	}

	@Test
	void removesPrivateResolutionRunsWhenRestartingAnIncompletePhase() throws Exception {
		Path target = temporaryDirectory.resolve("restart-resolution-runs-store");
		Path componentRuns;
		Path valueComponentRuns;
		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.RESOLVE_IDS);
			componentRuns = Files.createDirectory(workspace.directory().resolve("resolved-component-runs"));
			valueComponentRuns = Files.createDirectory(workspace.directory().resolve("resolved-value-component-runs"));
			Files.writeString(componentRuns.resolve("partial.run"), "partial");
			Files.writeString(valueComponentRuns.resolve("partial.run"), "partial");
		}

		try (BulkLoadWorkspace workspace = openWorkspace(target)) {
			workspace.startPhase(BulkLoadPhase.RESOLVE_IDS);

			assertThat(componentRuns).doesNotExist();
			assertThat(valueComponentRuns).doesNotExist();
		}
	}

	private BulkLoadWorkspace openWorkspace(Path target) throws Exception {
		return BulkLoadWorkspace.open(target, null, ProgressListener.NONE, 1, 1, BulkCompression.FASTEST);
	}

	private CanonicalStatementStager stager(Path directory) throws Exception {
		return new CanonicalStatementStager(directory, new LmdbStoreConfig("spoc,psoc"), 4, 4, 64 * 1024L,
				BulkCompression.FASTEST);
	}

	private static org.eclipse.rdf4j.model.Statement statement(String suffix) {
		var values = SimpleValueFactory.getInstance();
		return values.createStatement(values.createIRI("urn:sidecar:subject-" + suffix),
				values.createIRI("urn:sidecar:predicate"), values.createIRI("urn:sidecar:object-" + suffix));
	}
}
